import React, { useState, useEffect } from "react";
import Header from "../components/Header";
import Footer from "../components/Footer";
import RoomGrid from "../components/RoomGrid";
import BookingControls from "../components/BookingControls";
import "../Styles/Styles.css"; // Import global styles

const HomePage = () => {
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(false); // ✅ Add Loading State

  // Fetch Rooms
  const fetchRooms = async () => {
    try {
      setLoading(true);
      const res = await fetch("http://localhost:5000/api/bookings/rooms");
      const data = await res.json();
      if (Array.isArray(data)) {
        setRooms(data);
      } else {
        console.error("Invalid response: Expected an array", data);
        setRooms([]);
      }
    } catch (err) {
      console.error("Error fetching rooms:", err);
      setRooms([]);
    } finally {
      setLoading(false);
    }
  };

  // Load rooms on page load
  useEffect(() => {
    fetchRooms();
  }, []);

  // Book Rooms
  const bookRooms = async (count) => {
    try {
      setLoading(true);
      const res = await fetch("http://localhost:5000/api/bookings/book", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ count }),
      });
      const data = await res.json();
      alert(`Booked Rooms: ${data.bookedRooms.join(", ")}`);
      await fetchRooms(); // ✅ Fetch only ONCE
    } catch (err) {
      console.error("Booking failed:", err);
    } finally {
      setLoading(false);
    }
  };

  // Randomize Rooms
  const randomizeRooms = async () => {
    try {
      setLoading(true);
      await fetch("http://localhost:5000/api/bookings/randomize", {
        method: "POST",
      });
      await fetchRooms(); // ✅ Fetch only ONCE
    } catch (err) {
      console.error("Randomization failed:", err);
    } finally {
      setLoading(false);
    }
  };

  // Reset Rooms
  const resetRooms = async () => {
    try {
      setLoading(true);
      const res = await fetch("http://localhost:5000/api/bookings/reset", {
        method: "POST",
      });
      const data = await res.json();
      setRooms(data.rooms || []);
    } catch (err) {
      console.error("Failed to reset rooms:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container">
      <Header />

      <main className="content">
        {/* Booking Controls */}
        <div className="booking-section">
          <h2>Book Your Room</h2>
          <BookingControls
            bookRooms={bookRooms}
            randomizeRooms={randomizeRooms}
            resetRooms={resetRooms}
          />
        </div>

        {/* Room Layout */}
        <div className="room-container">
          {/* Left-side Stairs/Lift */}
          <div className="stairs-lift">
            <span>Stairs / Lift</span>
          </div>

          {/* Room Grid */}
          <div className="building">
            {loading ? (
              <p>Loading rooms...</p>
            ) : (
              <RoomGrid rooms={rooms} />
            )}
          </div>
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default HomePage;
